// Espera hasta el siguiente frame
yield return null;

// Espera N segundos de tiempo de juego
yield return new WaitForSeconds(2f);

// Espera N segundos de tiempo real (no afectado por Time.timeScale)
yield return new WaitForSecondsRealtime(2f);

// Espera hasta el siguiente FixedUpdate
yield return new WaitForFixedUpdate();

// Espera hasta que una condición sea true
yield return new WaitUntil(() => estaEnElSuelo);

// Espera mientras una condición sea true
yield return new WaitWhile(() => estaVivo);

// Espera a que otra corrutina termine
yield return StartCoroutine(OtraCorrutina());

// Declarar una corrutina
IEnumerator EsperarYDisparar()
{
    Debug.Log("Preparando disparo...");
    yield return new WaitForSeconds(1.5f);  // Pausa 1.5 segundos
    Debug.Log("¡FUEGO!");
    Instantiate(proyectil, transform.position, Quaternion.identity);
}

// Iniciar la corrutina
StartCoroutine(EsperarYDisparar());

// Guardar referencia para poder detenerla
Coroutine miCorrutina = StartCoroutine(EsperarYDisparar());

// Detener una corrutina específica
StopCoroutine(miCorrutina);

// Detener TODAS las corrutinas del MonoBehaviour
StopAllCoroutines();

